(function trustedShellPolicyModule(global) {
  "use strict";

  // This is the single reviewed allowlist for both CSP layers. The checked-in
  // trusted-shell.html is generated from outerPolicyContent() and tests require
  // the generated bytes to remain in sync.
  const ALLOWLIST = Object.freeze({
    artifactScheme: "nmp-artifact:",
    outer: Object.freeze({
      // srcdoc inherits this policy. Inline compatibility injection and sealed
      // subresources therefore must be allowed at both policy layers.
      script: Object.freeze(["'self'", "'unsafe-inline'", "nmp-artifact:"]),
      style: Object.freeze(["'self'", "'unsafe-inline'", "nmp-artifact:"]),
      frame: Object.freeze(["'self'", "about:"]),
      image: Object.freeze(["nmp-artifact:", "data:", "blob:"]),
      media: Object.freeze(["nmp-artifact:", "data:", "blob:"]),
      font: Object.freeze(["nmp-artifact:", "data:"]),
      base: Object.freeze(["nmp-artifact:"])
    }),
    inner: Object.freeze({
      script: Object.freeze(["'unsafe-inline'", "nmp-artifact:"]),
      style: Object.freeze(["'unsafe-inline'", "nmp-artifact:"]),
      image: Object.freeze(["nmp-artifact:", "data:", "blob:"]),
      media: Object.freeze(["nmp-artifact:", "data:", "blob:"]),
      font: Object.freeze(["nmp-artifact:", "data:"])
    })
  });

  function directive(name, values) {
    return name + " " + (values.length === 0 ? "'none'" : values.join(" "));
  }

  function outerPolicyContent() {
    return [
      "default-src 'none'",
      directive("script-src", ALLOWLIST.outer.script),
      directive("style-src", ALLOWLIST.outer.style),
      directive("frame-src", ALLOWLIST.outer.frame),
      "connect-src 'none'",
      directive("img-src", ALLOWLIST.outer.image),
      directive("media-src", ALLOWLIST.outer.media),
      directive("font-src", ALLOWLIST.outer.font),
      "object-src 'none'",
      directive("base-uri", ALLOWLIST.outer.base),
      "form-action 'none'",
      "worker-src 'none'"
    ].join("; ");
  }

  function innerPolicyContent() {
    return [
      "default-src 'none'",
      directive("script-src", ALLOWLIST.inner.script),
      directive("style-src", ALLOWLIST.inner.style),
      directive("img-src", ALLOWLIST.inner.image),
      directive("media-src", ALLOWLIST.inner.media),
      "connect-src 'none'",
      directive("font-src", ALLOWLIST.inner.font),
      "object-src 'none'",
      "base-uri " + ALLOWLIST.artifactScheme,
      "form-action 'none'",
      "worker-src 'none'",
      "child-src 'none'"
    ].join("; ");
  }

  const policy = Object.freeze({
    ALLOWLIST,
    outerPolicyContent,
    innerPolicyContent
  });
  global.NMPTrustedShellPolicy = policy;

  if (typeof module !== "undefined" && module.exports) {
    module.exports = policy;
  }
})(typeof window === "undefined" ? globalThis : window);
